function F(name,w,h,fill,opts={}){const f=figma.createFrame();f.name=name;if(w!=null)f.resize(w,h);f.fills=fill?solid(fill):[];if(opts.radius!=null)f.cornerRadius=opts.radius;if(opts.lm){f.layoutMode=opts.lm;f.primaryAxisSizingMode=opts.psm||"AUTO";f.counterAxisSizingMode=opts.csm||"AUTO";f.itemSpacing=opts.gap||0;f.primaryAxisAlignItems=opts.pa||"MIN";f.counterAxisAlignItems=opts.ca||"CENTER";if(opts.pad!=null){f.paddingLeft=f.paddingRight=f.paddingTop=f.paddingBottom=opts.pad;}if(opts.padX!=null){f.paddingLeft=f.paddingRight=opts.padX;}if(opts.padY!=null){f.paddingTop=f.paddingBottom=opts.padY;}}return f;}
