const COL={bg:"#F6F8FB",surface:"#FFFFFF",ink:"#0F1B2D",sub:"#6B7A90",brand:"#1573FE",up:"#0FA958",down:"#E5484D",line:"#E8EDF4",chip:"#EEF4FF"};
const solid=h=>[{type:"SOLID",color:rgb(h)}];
function T(chars,fam,style,size,color,opts={}){
  const t=figma.createText();t.fontName={family:fam,style};t.fontSize=size;t.characters=chars;
  t.fills=solid(color);if(opts.name)t.name=opts.name;
  if(opts.w){t.resize(opts.w,t.height);t.textAutoResize="HEIGHT";}
  if(opts.align)t.textAlignHorizontal=opts.align;
  if(opts.lh)t.lineHeight={value:opts.lh,unit:"PIXELS"};
  return t;
}
function auto(name,dir,gap,pad,opts={}){
  const f=figma.createFrame();f.name=name;f.layoutMode=dir;f.itemSpacing=gap;
  if(pad!==undefined){f.paddingLeft=f.paddingRight=f.paddingTop=f.paddingBottom=pad;}
  if(opts.px!==undefined){f.paddingLeft=f.paddingRight=opts.px;}
  if(opts.py!==undefined){f.paddingTop=f.paddingBottom=opts.py;}
  f.primaryAxisSizingMode=opts.fixW?"FIXED":"AUTO";f.counterAxisSizingMode=opts.fixH?"FIXED":"AUTO";
  if(opts.fill)f.fills=solid(opts.fill);else f.fills=[];
  if(opts.r)f.cornerRadius=opts.r;
  if(opts.counterAlign)f.counterAxisAlignItems=opts.counterAlign;
  if(opts.primaryAlign)f.primaryAxisAlignItems=opts.primaryAlign;
  return f;
}
function inst(comp,name){const i=comp.createInstance();if(name)i.name=name;return i;}
function icon(comp,size,color){
  const i=inst(comp);i.resize(size,size);
  if(color){const vs=i.findAllWithCriteria({types:["VECTOR","ELLIPSE","RECTANGLE","LINE"]});
    for(const v of vs){try{if(v.fills&&v.fills.length)v.fills=solid(color);}catch(e){}
      try{if(v.strokes&&v.strokes.length)v.strokes=solid(color);}catch(e){}}}
  return i;
}
