  let s=" ".repeat(d)+n.type+" "+n.name;
  if(n.type==="TEXT")s+=" «"+n.characters+"»";
  if(n.type==="INSTANCE")s+=" (main:"+(n.mainComponent?n.mainComponent.name:"?")+")";
  s+="\n";
  if("children" in n&&d<4)for(const ch of n.children)s+=dump(ch,d+1);
  return s;
}
