function auto(name,dir,gap,pad,opts={}){
  const f=figma.createFrame();f.name=name;f.layoutMode=dir;f.itemSpacing=gap;
  if(pad!==undefined){f.paddingLeft=f.paddingRight=f.paddingTop=f.paddingBottom=pad;}
  if(opts.px!==undefined){f.paddingLeft=f.paddingRight=opts.px;}
  if(opts.py!==undefined){f.paddingTop=f.paddingBottom=opts.py;}
  f.primaryAxisSizingMode=opts.fixW?"FIXED":"AUTO";f.counterAxisSizingMode=opts.fixH?"FIXED":"AUTO";
  if(opts.fill)f.fills=solid(opts.fill);else f.fills=[];
  if(opts.r)f.cornerRadius=opts.r;
  if(opts.counterAlign)f.counterAxisAlignItems=opts.counterAlign;
  if(opts.primaryAlign)f.primaryAxisAlignItems=opts.primaryAlign;
  return f;
}
function inst(comp,name){const i=comp.createInstance();if(name)i.name=name;return i;}
function recolor(node,color){
