const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
const out={};
for(const f of page.children.filter(n=>n.type==="FRAME"&&/^\d\d_/.test(n.name))){
  const issues=[];
  const walk=(n,depth)=>{
    if(n.width<2&&n.type!=="RECTANGLE"&&n.type!=="VECTOR"&&n.type!=="LINE")issues.push(n.name+" w"+Math.round(n.width));
    if(n.height<2&&n.type!=="RECTANGLE"&&n.type!=="VECTOR"&&n.type!=="LINE"&&n.type!=="TEXT")issues.push(n.name+" h"+Math.round(n.height));
    if("children" in n&&depth<6)for(const c of n.children)walk(c,depth+1);
  };
  walk(f,0);
  out[f.name]=issues.length?issues.slice(0,8):"OK";
}
return JSON.stringify(out,null,1);

